return new {playing=EditorApplication.isPlaying,path=UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene().path,dirty=UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene().isDirty,sources=Resources.FindObjectsOfTypeAll<AudioSource>().Select(x=>new{name=x.name,clip=x.clip!=null?x.clip.name:null,volume=x.volume,mixer=x.outputAudioMixerGroup!=null?x.outputAudioMixerGroup.name:null,scene=x.gameObject.scene.path}).ToArray(),qualities=QualitySettings.names};
